function refreshResources(){for(const r of resources){if(s.harvested[r.id]&&s.harvested[r.id]<=s.elapsed){delete s.harvested[r.id];delete s.damage[r.id]}r.g.visible=(!s.harvested[r.id]||s.harvested[r.id]<=s.elapsed)&&Math.hypot(s.x-r.x,s.z-r.z)<85}for(const l of loot)l.g.visible=!s.opened[l.id]&&Math.hypot(s.x-l.x,s.z-l.z)<100}
function makeFire(x,z){const g=group(scene,x,height(x,z),z);for(let i=0;i<8;i++){const a=i*TAU/8;orb(g,0x858377,Math.sin(a)*.45,.13,Math.cos(a)*.45,.19,.17,.2)}for(let i=0;i<2;i++){const m=cyl(g,0x62412c,0,.2,0,.08,.65,.08);m.rotation.z=Math.PI/2;m.rotation.y=i*Math.PI/2}const flame=cone(g,0xff9b32,0,.55,0,.23,.68,.23),inner=cone(g,0xffe5a1,0,.45,0,.13,.44,.13),light=new T.PointLight(0xffa34f,8,13,2);light.position.y=.9;g.add(light);fires.push({x,z,g,flame,inner,light})}
function restoreFires(){for(const f of fires)scene.remove(f.g);fires.length=0;for(const f of s.fires)makeFire(f.x,f.z)}
function nearFire(){return fires.some(f=>Math.hypot(s.x-f.x,s.z-f.z)<4)}
function wolfModel(x,z,kind='wolf'){const g=group(scene,x,height(x,z),z);orb(g,0x777871,0,.59,0,.36,.36,.71);orb(g,0x8b8e84,0,.73,.62,.25,.25,.33);orb(g,0x656961,0,.63,.85,.18,.16,.2);for(const sign of [-1,1]){cone(g,0x636a61,sign*.13,.99,.57,.095,.24,.09);box(g,0xe4ba6f,sign*.105,.77,.84,.04,.035,.03)}const legs=[];for(const xx of [-.23,.23])for(const zz of [-.37,.36]){const l=group(g,xx,.47,zz);cyl(l,0x666a64,0,-.23,0,.074,.47,.074);legs.push(l)}const tail=cyl(g,0x6d736a,0,.65,-.83,.09,.55,.09);tail.rotation.x=-Math.PI/3;if(kind==='boar'){g.scale.set(1.25,.85,1.03);for(const side of [-1,1])orb(g,0xd2c5a0,side*.17,.57,.97,.055,.06,.16);orb(g,0x6f5143,0,.63,0,.38,.4,.73)}else if(kind==='deer'){g.scale.set(.88,1.45,1);for(const side of [-1,1]){const antler=cyl(g,0x9c8056,side*.18,1.14,.58,.032,.42,.032);antler.rotation.z=side*-.42;cyl(g,0xa58a62,side*.24,1.27,.56,.026,.23,.026)}orb(g,0x9b7251,0,.60,0,.36,.35,.71)}return{g,legs,x,z,homeX:x,homeZ:z,kind,maxHp:HP[kind],hp:HP[kind],dead:false,respawn:0,hit:0,phase:0}}
const passiveKinds=['rabbit','deer','fox'],nightKind=k=>NIGHT_MOBS.includes(k);
