 if(b.kind==='ramp'){const ramp=box(g,boards[0],0,.28,0,2,.16,2.12);ramp.rotation.x=-.28;for(const x of [-.82,.82]){const rail=box(g,timber,x,.20,0,.12,.16,2.1);rail.rotation.x=-.28}}
 if(b.kind==='slopedroof'){for(let i=0;i<8;i++){const m=box(g,boards[i%4],(i-3.5)*.26,.55,0,.25,.15,2.4);m.rotation.x=Math.PI/6}}
