function clearBuilt(){for(const v of built.values())scene.remove(v.g);built.clear()}
function restoreBuilt(){clearBuilt();for(const b of s.buildings)built.set(b.id,pieceModel(b))}
function hideGhost(){if(ghost)ghost.g.visible=false;currentPlan=null}
function exitBuild(){building=false;aim=null;hideGhost();$('build-hud').hidden=$('build-crosshair').hidden=$('build-menu').hidden=true;if(state==='buildmenu'){state='play';$('touch').hidden=!touchDevice}}
function openBuildMenu(){if(state!=='play'&&state!=='buildmenu')return;if(!s.inventory.hammer&&!s.inventory.bench&&!has(s,{wood:4})){toast('Raccogli 4 legna per il banco.');return}state='buildmenu';if(s.inventory.hammer&&s.equipped.weapon!=='hammer'){equip(s,'hammer');rebuildActor();renderHotbar()}keys.clear();touchMove={x:0,y:0};runTouch=false;$('touch').hidden=true;$('build-menu').hidden=false;hideGhost();const grid=$('piece-grid');grid.replaceChildren();if(!s.inventory.hammer||!benchNear(s))buildKind='bench';for(const [id,p] of Object.entries(PIECES).filter(([id])=>id==='bench'||s.inventory.hammer&&benchNear(s)))tile(grid,id,p.name,0,()=>pieceDetail(id),!!p.bench&&!benchNear(s)||!(id==='bench'&&s.inventory.bench)&&!has(s,p.cost));pieceDetail(buildKind)}
function pieceDetail(id){buildKind=id;const p=PIECES[id],d=$('piece-detail');d.innerHTML=art(id)+'<p class="kicker">'+(p.bench?'RICHIEDE BANCO DA LAVORO':'COSTRUZIONE BASE')+'</p><h3>'+p.name+'</h3><p>'+p.desc+'</p>';const c=document.createElement('div');d.append(c);costList(c,id==='bench'&&s.inventory.bench?{bench:1}:p.cost);actionButton(d,'SELEZIONA PEZZO',()=>{state='play';building=true;$('build-menu').hidden=true;$('touch').hidden=!touchDevice;$('build-hud').hidden=$('build-crosshair').hidden=false;updateBuild()})}
function closeBuildMenu(){if(state==='buildmenu'){state='play';$('build-menu').hidden=true;$('touch').hidden=!touchDevice;if(!building)exitBuild()}}
const ray=new T.Raycaster(),pointer=new T.Vector2();
function aimPoint(){if(aim&&!touchDevice){pointer.set(aim.x/innerWidth*2-1,-aim.y/innerHeight*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObject(ground,false)[0];if(hit&&Math.hypot(hit.point.x-s.x,hit.point.z-s.z)<=7)return hit.point}return{x:s.x+Math.sin(camYaw)*3.6,z:s.z+Math.cos(camYaw)*3.6}}
function updateBuild(){if(!building||state!=='play'){hideGhost();return}const pos=aimPoint();let plan=planPiece(s,buildKind,pos.x,pos.z,buildRot,height,dry(pos.x,pos.z));if(buildKind!=='bench'&&!s.inventory.hammer){plan.ok=false;plan.reason='Serve il martello'}if(plan.piece){const b=plan.piece;if(!dry(b.x,b.z)){plan.ok=false;plan.reason='Terreno sommerso'}if(['wall','door','fence','bench'].includes(b.kind)&&Math.hypot(b.x-s.x,b.z-s.z)<1.1){plan.ok=false;plan.reason='Allontanati dal pezzo'}if(resources.some(r=>r.g.visible&&['wood','oak'].includes(r.kind)&&Math.hypot(b.x-r.x,b.z-r.z)<1.1)){plan.ok=false;plan.reason='Rimuovi l’albero prima di costruire'}if(!ghost||ghostKind!==buildKind){if(ghost)scene.remove(ghost.g);ghost=pieceModel(b,true);ghostKind=buildKind}ghost.g.visible=true;ghost.g.position.set(b.x,b.y,b.z);ghost.g.rotation.y=b.rot*Math.PI/2;ghost.g.traverse(m=>{if(m.isMesh)m.material=ghostMaterials[plan.ok?0:1]})}currentPlan=plan;$('build-label').textContent=PIECES[buildKind].name;$('build-status').textContent=plan.ok?'Posizione valida · clic o POSA':plan.reason;$('build-status').classList.toggle('invalid',!plan.ok);$('build-place').disabled=!plan.ok;demolishTarget=nearestPiece(pos.x,pos.z,2.0);$('build-remove').disabled=!demolishTarget;$('build-remove').title=demolishTarget?'Demolisci '+PIECES[demolishTarget.kind].name:'Nessun pezzo vicino'}
function nearestPiece(x,z,range=2){let best=null,dist=range;for(const b of s.buildings){const d=Math.hypot(b.x-x,b.z-z)+(b.kind===buildKind?-.15:0);if(d<dist){best=b;dist=d}}return best}
function placeBuild(){if(!building||state!=='play')return;updateBuild();if(!currentPlan?.ok){toast(currentPlan?.reason||'Posizione non valida');return}const b=placePiece(s,currentPlan);if(b){built.set(b.id,pieceModel(b));toast('Costruito: '+PIECES[b.kind].name);updateHud();save();updateBuild()}}
function demolish(){if(!building||state!=='play')return;updateBuild();const b=demolishTarget;if(!b||Math.hypot(s.x-b.x,s.z-b.z)>7){toast('Punta un pezzo vicino da demolire.');return}if(b.kind==='post'&&s.buildings.some(q=>['roof','slopedroof','beam'].includes(q.kind)&&q.x===b.x&&q.z===b.z&&!s.buildings.some(v=>['wall','door','window'].includes(v.kind)&&Math.abs(v.x-q.x)+Math.abs(v.z-q.z)===1))){toast('Rimuovi prima la copertura sostenuta.');return}if(['wall','door','window'].includes(b.kind)&&s.buildings.some(q=>['roof','slopedroof','beam'].includes(q.kind)&&Math.abs(q.x-b.x)+Math.abs(q.z-b.z)===1&&!s.buildings.some(v=>v.id!==b.id&&['wall','door','window'].includes(v.kind)&&Math.abs(v.x-q.x)+Math.abs(v.z-q.z)===1))){toast('Rimuovi prima il tetto sostenuto.');return}if(b.kind==='floor'&&s.buildings.some(q=>['roof','slopedroof','beam'].includes(q.kind)&&q.x===b.x&&q.z===b.z||['wall','door','window'].includes(q.kind)&&Math.abs(q.x-b.x)+Math.abs(q.z-b.z)===1)){toast('Rimuovi prima pareti e tetto adiacenti.');return}if(removePiece(s,b.id)){scene.remove(built.get(b.id).g);built.delete(b.id);toast('Demolito · materiali recuperati');updateHud();save();updateBuild()}}
function nearStructure(){return s.buildings.filter(b=>['door','bench'].includes(b.kind)&&Math.hypot(s.x-b.x,s.z-b.z)<2.6).sort((a,b)=>Math.hypot(s.x-a.x,s.z-a.z)-Math.hypot(s.x-b.x,s.z-b.z))[0]}
function structureUse(b){if(b.kind==='bench'){openBag('bench');return}b.open=!b.open;const m=built.get(b.id);if(m?.hinge)m.hinge.rotation.y=b.open?Math.PI/2:0;save();toast(b.open?'Porta aperta':'Porta chiusa')}
function blockedByBuild(x,z){return s.buildings.some(b=>{if(b.kind==='post')return Math.hypot(x-b.x,z-b.z)<.34;if(b.kind==='bench')return Math.abs(x-b.x)<.95&&Math.abs(z-b.z)<.75;if(!['wall','door','fence','window'].includes(b.kind)||b.kind==='door'&&b.open)return false;const dx=Math.abs(x-b.x),dz=Math.abs(z-b.z);return b.rot%2?dx<.38&&dz<1.10:dz<.38&&dx<1.10})}
function walkHeight(x,z){let y=height(x,z);for(const b of s.buildings)if(b.kind==='floor'&&Math.abs(x-b.x)<1.03&&Math.abs(z-b.z)<1.03)y=Math.max(y,b.y+.12);else if(b.kind==='ramp'&&Math.abs(x-b.x)<1&&Math.abs(z-b.z)<1){const a=b.rot*Math.PI/2,localZ=Math.sin(a)*(x-b.x)+Math.cos(a)*(z-b.z);y=Math.max(y,b.y+.32+localZ*.28)}return y}
function sheltered(){return s.buildings.some(b=>['roof','slopedroof'].includes(b.kind)&&Math.abs(s.x-b.x)<1.1&&Math.abs(s.z-b.z)<1.1)}
const resourceNames={oak:'Quercia',cactus:'Cactus da frutto',icecrystal:'Cristallo di gelo',reed:'Giunco',amber:'Deposito di ambra',rabbit:'Lepre',fox:'Volpe',scorpion:'Scorpione',icewolf:'Lupo del gelo',crocodile:'Coccodrillo',shade:'Ombra errante',forestwraith:'Spettro del bosco',sandstalker:'Predatore delle dune',frostwraith:'Spettro del gelo',swampwraith:'Spettro palustre',wood:'Albero',stone:'Roccia',fiber:'Pianta fibrosa',berries:'Cespuglio di bacche',chest:'Forziere',wolf:'Lupo',boar:'Cinghiale',deer:'Cervo',flint:'Deposito di selce',copper:'Minerale di rame',clay:'Argilla',mushroom:'Funghi',water:'Acqua'};
function searchNear(includeAnimals=true){let best=null,d=s.equipped.weapon==='spear'?3.3:2.9;for(const r of [...resources,...loot]){if(!r.g.visible)continue;const v=Math.hypot(s.x-r.x,s.z-r.z);if(v<d){best=r;d=v}}if(includeAnimals)for(const w of wolves){if(w.dead)continue;const v=Math.hypot(s.x-w.x,s.z-w.z);if(v<d){best=w;d=v}}if(waterDist(s.x,s.z)<22&&(!best||d>2.5))return{kind:'water'};return best}
function targetHealth(r){return r?.maxHp?Math.max(0,r.hp??r.maxHp-(s.damage[r.id]||0)):0}
function useChest(r,broken=false){if(s.opened[r.id])return;s.opened[r.id]=true;r.g.visible=false;delete s.damage[r.id];const found=r.id==='traveller'?{hide:1,fiber:3,berries:2}:r.id==='royal'?{hide:2,stone:4,meat:2}:r.id==='ancestors'?{fiber:7,wood:5,hide:1}:{hide:2,meat:3,wood:4};if(broken)found.wood=(found.wood||0)+1;for(const [k,n] of Object.entries(found))add(s,k,n);toast('Forziere: '+Object.entries(found).map(([k,n])=>ITEMS[k]+' +'+n).join(' · '));updateHud();save()}
function hitTarget(r){if(state!=='play'||attackCooldown>0||s.stamina<3||!r||!r.maxHp)return false;const range=s.equipped.weapon==='spear'?3.3:2.9;if(Math.hypot(s.x-r.x,s.z-r.z)>range)return false;const dmg=hitDamage(s.equipped.weapon,r.kind);attackCooldown=s.equipped.weapon ? .55 : .48;attackTime=.32;s.stamina=clamp(s.stamina-(s.equipped.weapon?4:2));const hp=Math.max(0,targetHealth(r)-dmg);if(r.hp!==undefined){r.hp=hp;r.hit=.55;if(!hp){r.dead=true;r.g.visible=false;r.respawn=s.elapsed+150;s.kills++;if(nightKind(r.kind)){add(s,'bone',2);if(r.kind==='swampwraith')add(s,'venom',1);toast(resourceNames[r.kind]+' sconfitto · ossa raccolte')}else{add(s,'hide',r.kind==='boar'?2:1);add(s,'meat',r.kind==='rabbit'?1:r.kind==='deer'?3:2);if(r.kind==='icewolf')add(s,'fur',2);if(['icewolf','crocodile','scorpion'].includes(r.kind))add(s,'fang',1);toast(resourceNames[r.kind]+' sconfitto · bottino raccolto')}}else toast(resourceNames[r.kind]+' · -'+dmg+' PV')}else{s.damage[r.id]=r.maxHp-hp;r.shake=.23;if(!hp){if(r.kind==='chest'){useChest(r,true);return true}const n=r.kind==='wood'?6:r.kind==='stone'?5:r.kind==='fiber'?3:r.kind==='copper'?4:r.kind==='clay'?4:3;add(s,r.kind,n);if(r.kind==='wood'||r.kind==='oak')add(s,'resin',1);s.harvested[r.id]=s.elapsed+150;r.g.visible=false;toast('+'+n+' '+ITEMS[r.kind]+(r.kind==='wood'?' · +1 resina':''))}else toast(resourceNames[r.kind]+' · -'+dmg+' PV')}updateHud();save();return true}
function interact(){if(state!=='play')return;if(building){placeBuild();return}const structure=nearStructure();if(structure){structureUse(structure);return}const r=searchNear();if(!r){toast('Avvicinati a una risorsa.');return}if(r.kind==='water'){drink(s);toast('Hai bevuto acqua.');return}if(r.kind==='chest'){useChest(r);return}hitTarget(r)}
function foodAction(){if(state!=='play')return;const id=s.hotbar[s.selected];if((['food','berries','mushroom','cactus'].includes(id)&&eat(s,id))||eat(s,'food')||eat(s,'berries')||eat(s,'mushroom')||eat(s,'cactus')){toast('Hai mangiato.');updateHud();save()}else toast('Non hai cibo nello zaino.')}
function attack(){if(building){placeBuild();return}if(state!=='play'||attackCooldown>0||s.stamina<3)return;let target=null,best=s.equipped.weapon==='spear'?3.3:2.9;for(const w of wolves){if(w.dead)continue;const d=Math.hypot(s.x-w.x,s.z-w.z);if(d<best){target=w;best=d}}if(!target)target=searchNear(false);if(!hitTarget(target)){attackCooldown=.48;attackTime=.32;s.stamina=clamp(s.stamina-2)}}
function targetHUD(){const el=$('target-hud');if(building){el.hidden=$('interaction').hidden=true;return}const structure=nearStructure();if(structure){el.hidden=false;$('target-name').textContent=PIECES[structure.kind].name;$('target-hp').textContent=PIECES[structure.kind].hp+' PV';$('target-fill').style.width='100%';$('interaction').hidden=false;$('interaction').textContent='[ E ] · '+(structure.kind==='bench'?'Usa banco da lavoro':structure.open?'Chiudi porta':'Apri porta');return}const r=searchNear();el.hidden=!r?.maxHp;if(!el.hidden){const hp=targetHealth(r);$('target-name').textContent=resourceNames[r.kind];$('target-hp').textContent=hp+' / '+r.maxHp;$('target-fill').style.width=hp/r.maxHp*100+'%'}$('interaction').hidden=!r;if(r){const action=r.kind==='water'?'Bevi acqua':r.kind==='chest'?'Apri forziere':'Colpisci '+resourceNames[r.kind].toLowerCase();$('interaction').textContent=(touchDevice?'TOCCA E':'[ E ]')+' · '+action}}
function wolfTick(dt){nightTick(dt);for(const w of wolves){if(w.dead){if(!nightKind(w.kind)&&s.elapsed>=w.respawn){w.dead=false;w.hp=w.maxHp;w.x=w.homeX;w.z=w.homeZ;w.g.visible=true}continue}w.hit=Math.max(0,w.hit-dt);const dx=s.x-w.x,dz=s.z-w.z,d=Math.hypot(dx,dz);w.g.visible=d<90;if(d>100)continue;let vx=0,vz=0;if(passiveKinds.includes(w.kind)&&d<12&&d>.1){vx=-dx/d;vz=-dz/d}else if(!passiveKinds.includes(w.kind)&&d<(nightKind(w.kind)?28:13)&&d>1.2){vx=dx/d;vz=dz/d}else if(d>=(nightKind(w.kind)?28:13)){const tx=w.homeX+Math.sin(s.elapsed*.16+w.homeX)*4-w.x,tz=w.homeZ+Math.cos(s.elapsed*.13+w.homeZ)*4-w.z,dd=Math.hypot(tx,tz);if(dd>.4){vx=tx/dd;vz=tz/dd}}const speed=nightKind(w.kind)?3.25:d<13?(passiveKinds.includes(w.kind)?4.7:w.kind==='boar'?2.5:2.9):.8;if(w.hit>.3){vx=-vx;vz=-vz}const nx=clamp(w.x+vx*speed*dt,-LIMIT,LIMIT),nz=clamp(w.z+vz*speed*dt,-LIMIT,LIMIT);if(!blockedByBuild(nx,nz)){w.x=nx;w.z=nz}w.g.position.set(w.x,height(w.x,w.z),w.z);if(vx||vz)w.g.rotation.y=Math.atan2(vx,vz);w.phase+=dt*(d<13?11:4);w.legs.forEach((leg,i)=>leg.rotation.x=Math.sin(w.phase+(i%2?Math.PI:0)+(i>1?Math.PI:0))*.4);if(!passiveKinds.includes(w.kind)&&d<1.65&&w.hit<=0&&jumpY<.85){w.hit=1.25;s.health=clamp(s.health-(nightKind(w.kind)?14:w.kind==='crocodile'?18:w.kind==='boar'?12:9));toast(resourceNames[w.kind]+' ti ha ferito!')}}}
function updateHud(){renderHotbar();$('night-warning').hidden=!isNight();for(const k of ['health','hunger','thirst','stamina']){$(k+'-value').textContent=Math.ceil(s[k])+'%';$(k+'-bar').style.width=s[k]+'%'}const t=Math.floor(s.time),day=Math.floor(t/1440)+1,hh=Math.floor(t/60)%24,mm=t%60;$('clock').textContent='GIORNO '+day+' · '+String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0');const loc=landmarks.find(l=>Math.hypot(s.x-l.x,s.z-l.z)<16);$('region').textContent=(loc?.name||biomeAt(s.x,s.z).name).toUpperCase();const inv=s.inventory;if(!s.buildings.some(b=>b.kind==='bench')){$('quest').textContent='Costruisci il banco da lavoro';$('quest-sub').textContent=inv.bench?'Banco pronto · B per posarlo':'C · '+Math.min(4,inv.wood||0)+'/4 legna'}else if(!WEAPONS.some(k=>inv[k])){$('quest').textContent='Crea la tua prima arma';$('quest-sub').textContent='Ascia: '+Math.min(2,inv.wood||0)+'/2 legna · '+Math.min(3,inv.stone||0)+'/3 pietra · '+Math.min(1,inv.fiber||0)+'/1 fibra'}else if(!s.inventory.hammer){$('quest').textContent='Crea un martello';$('quest-sub').textContent='3 legna · 2 pietra'}else if(!s.buildings.some(b=>b.kind==='bench')){$('quest').textContent='Posa un banco da lavoro';$('quest-sub').textContent='B · 4 legna'}else if(!s.buildings.some(b=>b.kind==='roof')){$('quest').textContent='Costruisci il primo riparo';$('quest-sub').textContent='Lavora tavole al banco · B per costruire'}else if(!s.equipped.tunic){$('quest').textContent='Vestiti per la notte';$('quest-sub').textContent='Tunica: '+Math.min(6,inv.fiber||0)+'/6 fibra · '+Math.min(1,inv.hide||0)+'/1 pelle'}else if(!fires.length){$('quest').textContent='Accendi il tuo primo falò';$('quest-sub').textContent='5 legna · 4 pietra'}else{$('quest').textContent='Esplora le antiche rovine';$('quest-sub').textContent=Object.keys(s.opened).length+'/'+loot.length+' forzieri · '+s.kills+' animali sconfitti'}drawMap()}
let mapBackground=null;function drawMap(){const c=$('map'),q=c.getContext('2d'),m=(x)=>70+x/LIMIT*67;if(!mapBackground){mapBackground=document.createElement('canvas');mapBackground.width=mapBackground.height=140;const ctx=mapBackground.getContext('2d');for(let yy=0;yy<140;yy+=5)for(let xx=0;xx<140;xx+=5){const bio=biomeAt((xx-70)/67*LIMIT,(yy-70)/67*LIMIT);ctx.fillStyle='#'+bio.base.toString(16).padStart(6,'0');ctx.fillRect(xx,yy,5,5)}}q.drawImage(mapBackground,0,0);q.strokeStyle='#94a88733';for(let i=10;i<140;i+=20){q.beginPath();q.moveTo(i,0);q.lineTo(i,140);q.moveTo(0,i);q.lineTo(140,i);q.stroke()}q.fillStyle='#4e9499';for(const l of LAKES){q.beginPath();q.arc(m(l.x),m(l.z),l.r/LIMIT*67,0,TAU);q.fill()}q.fillStyle='#dfbe83';for(const l of landmarks.filter(l=>!l.name.includes('Lago'))){q.fillRect(m(l.x)-2,m(l.z)-2,4,4)}for(const f of fires){q.fillStyle='#ffb252';q.fillRect(m(f.x)-2,m(f.z)-2,4,4)}q.save();q.translate(m(s.x),m(s.z));q.rotate(-s.yaw);q.fillStyle='#fff2cb';q.beginPath();q.moveTo(0,5);q.lineTo(-4,-4);q.lineTo(4,-4);q.closePath();q.fill();q.restore()}
let benchSession=false;function openBag(mode){if(state!=='play'&&state!=='bag')return;if(building)exitBuild();if(state!=='bag')benchSession=mode==='bench'&&!!nearStructure()&&nearStructure().kind==='bench';state='bag';bagMode=mode==='bench'?'craft':mode;keys.clear();touchMove={x:0,y:0};runTouch=false;$('bag').hidden=false;$('touch').hidden=true;renderBag()}
function closeBag(){if(state!=='bag')return;benchSession=false;state='play';$('bag').hidden=true;$('touch').hidden=!touchDevice}
const glyphs={wood:'▥',stone:'◆',fiber:'❧',berries:'●',hide:'▧',meat:'▰',food:'🍖',axe:'🪓',pickaxe:'⛏',sword:'⚔',spear:'↗',tunic:'👕',boots:'🥾',campfire:'🔥'};
let assignIndex=0,lastHotbar='';
function renderHotbar(){const key=JSON.stringify([s.hotbar,s.selected,s.inventory,s.equipped]);if(lastHotbar===key)return;lastHotbar=key;const row=$('hotbar');row.replaceChildren();for(let i=0;i<9;i++){const id=s.hotbar[i],b=document.createElement('button');b.className='slot'+(s.selected===i?' selected':'');b.type='button';b.title=id?ITEMS[id]:'Mani nude / slot vuoto';b.setAttribute('aria-label','Slot '+(i+1)+' '+b.title);b.setAttribute('aria-pressed',String(i===s.selected));const num=document.createElement('small');num.textContent=i+1;const ico=document.createElement('b');if(id)ico.innerHTML=art(id);else ico.textContent=i===0?'✊':'';const n=document.createElement('em');n.textContent=id?(s.inventory[id]||0):'';b.append(num,ico,n);b.addEventListener('click',()=>chooseSlot(i));row.append(b)}const id=s.hotbar[s.selected];$('selected-item').textContent=id?ITEMS[id]:'Mani nude'}
function chooseSlot(i){if(state!=='play'&&state!=='bag')return;if(!selectSlot(s,i))return;rebuildActor();renderHotbar();save()}
function renderAssign(){const row=$('assign-slots');row.replaceChildren();for(let i=0;i<9;i++){const b=document.createElement('button');b.type='button';b.className='assign-slot'+(assignIndex===i?' selected':'');b.textContent=(i+1)+(s.hotbar[i]?' · '+(glyphs[s.hotbar[i]]||'◆'):'');b.title=s.hotbar[i]?ITEMS[s.hotbar[i]]:'Slot vuoto';b.addEventListener('click',()=>{assignIndex=i;renderBag()});row.append(b)}}
