function art(id){const alias={oak:'wood',cactus:'berries',icecrystal:'stone',reed:'fiber',amber:'resin',bone:'stone',fang:'stone',fur:'hide',venom:'resin',linen:'fiber',wintercoat:'tunic',post:'wood',beam:'plank',window:'wall',ramp:'floor',slopedroof:'roof',flint:'stone',clay:'stone',copper:'stone',flintaxe:'axe'}[id]||id;const filter={flint:'brightness(.65)',clay:'sepia(1) saturate(1.7)',copper:'sepia(1) saturate(2) hue-rotate(110deg)',flintaxe:'brightness(1.3)'}[id]||'';return '<svg class="item-art" aria-hidden="true" viewBox="0 0 64 64" style="filter:'+filter+'">'+(shapes[alias]||shapes.stone)+'</svg>'}
const descriptions={oak:'Legno resistente esclusivo delle foreste.',cactus:'Frutto del deserto: recupera 22 punti fame.',icecrystal:'Cristallo esclusivo delle montagne.',reed:'Giunco delle paludi, necessario per tessere tela.',amber:'Ambra della foresta.',bone:'Resti delle creature notturne.',fang:'Zanna dei predatori.',fur:'Pelliccia per abiti invernali.',venom:'Essenza delle creature palustri.',linen:'Tessuto prodotto al banco da lavoro.',wood:'Tronchi per strumenti e costruzioni.',stone:'Pietra comune per utensili primitivi.',fiber:'Fibre vegetali per legature e tessuti.',berries:'Ripristinano 13 punti fame.',mushroom:'Ripristinano 18 punti fame.',hide:'Pelle animale per vestiti.',meat:'Cuocila vicino a un falò.',food:'Ripristina 38 punti fame.',plank:'Tavole lavorate al banco.',flint:'Pietra tagliente per strumenti avanzati.',resin:'Resina infiammabile ottenuta dagli alberi.',clay:'Materiale grezzo per ricette future.',copper:'Minerale grezzo; fusione in un futuro aggiornamento.'};
let selectedDetail='';
function actionButton(parent,label,fn,disabled=false){const b=document.createElement('button');b.className='secondary';b.type='button';b.textContent=label;b.disabled=disabled;b.addEventListener('click',fn);parent.append(b);return b}
function costList(parent,cost){parent.replaceChildren();for(const [id,n] of Object.entries(cost||{})){const d=document.createElement('div');d.className='cost-row'+((s.inventory[id]||0)<n?' missing':'');d.innerHTML=art(id)+'<span>'+ITEMS[id]+'</span><b>'+(s.inventory[id]||0)+' / '+n+'</b>';parent.append(d)}}
function tile(parent,id,name,n,onSelect,locked=false){const b=document.createElement('button');b.type='button';b.className='item-tile'+(locked?' locked':'');b.title=name;b.innerHTML=art(id)+'<span class="tile-name">'+name+'</span>'+(n?'<span class="tile-count">'+n+'</span>':'')+(locked?'<span class="tile-lock">◆</span>':'');for(const k of ['mouseenter','focus','click'])b.addEventListener(k,()=>{for(const x of parent.children)x.classList.toggle('selected',x===b);onSelect()});parent.append(b);return b}
function beginBenchPlacement(){if(!s.inventory.bench)return;closeBag();buildKind='bench';building=true;aim=null;$('build-hud').hidden=$('build-crosshair').hidden=false;updateBuild()}
function craftItem(r){if(!craft(s,r.id,nearFire(),benchSession&&benchNear(s)))return;if(r.id==='bench'){updateHud();save();beginBenchPlacement();return}if(r.id==='campfire'){take(s,'campfire');let x=clamp(s.x+Math.sin(s.yaw)*2,-LIMIT,LIMIT),z=clamp(s.z+Math.cos(s.yaw)*2,-LIMIT,LIMIT);if(!dry(x,z)){x=s.x;z=s.z}s.fires.push({x,z});makeFire(x,z)}$('bag-note').textContent='Creato: '+r.name;updateHud();save();renderBag()}
function detail(id){selectedDetail=id;const r=RECIPES.find(r=>r.id===id),isCraft=bagMode==='craft';$('detail-art').innerHTML=art(id);$('detail-tag').textContent=isCraft?(r.bench?'BANCO DA LAVORO':r.fire?'FALÒ':'CRAFTING BASE'):'NELLO ZAINO · '+(s.inventory[id]||0);$('detail-title').textContent=ITEMS[id];$('detail-desc').textContent=r?.desc||descriptions[id]||'Risorsa';const actions=$('detail-actions');actions.className='detail-actions';actions.replaceChildren();costList($('detail-cost'),isCraft?r.cost:{});
if(isCraft){if(benchSession&&s.inventory.hammer)actionButton(actions,'PEZZI DA COSTRUZIONE',()=>{closeBag();openBuildMenu()});const unique=[...WEAPONS,'tunic','boots','wintercoat'].includes(id)&&s.inventory[id],locked=r.bench&&!(benchSession&&benchNear(s))||r.fire&&!nearFire();actionButton(actions,unique?'GIÀ CREATO':locked?(r.bench?'SERVE IL BANCO':'SERVE IL FALÒ'):'CREA'+(r.qty?' ×'+r.qty:''),()=>craftItem(r),!!unique||locked||!has(s,r.cost)||id==='campfire'&&(s.fires.length>=30||!dry(s.x,s.z)))}else{const wearable=[...WEAPONS,'tunic','boots','wintercoat'].includes(id),edible=['berries','food','mushroom','cactus'].includes(id);if(id==='bench')actionButton(actions,'POSIZIONA BANCO',beginBenchPlacement);if(wearable||edible)actionButton(actions,wearable?(s.equipped.weapon===id||s.equipped[id]===true?'RIMUOVI':'EQUIPAGGIA'):'MANGIA',()=>{if(wearable){equip(s,id);rebuildActor()}else eat(s,id);updateHud();save();renderBag()});actionButton(actions,'ASSEGNA A SLOT '+(assignIndex+1),()=>{assignSlot(s,assignIndex,id);rebuildActor();renderHotbar();save();renderBag()})}}
