function step(dt){if(jumpY>0||jumpV>0){const j=jumpStep(jumpY,jumpV,dt);jumpY=j.y;jumpV=j.v}let x=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0)+touchMove.x,z=(keys.has('w')||keys.has('ArrowUp')?1:0)-(keys.has('s')||keys.has('ArrowDown')?1:0)-touchMove.y;const len=Math.hypot(x,z);const running=len>.1&&(keys.has('Shift')||runTouch)&&s.stamina>4;let speed=len>.1?(running?6.8:3.6):0;if(waterDist(s.x,s.z)<18)speed*=.65;moveSpeed+=(speed-moveSpeed)*Math.min(1,dt*9);if(len>.1){x/=Math.max(1,len);z/=Math.max(1,len);const {dx,dz}=movement(x,z,camYaw);const desired=Math.atan2(dx,dz),delta=Math.atan2(Math.sin(desired-s.yaw),Math.cos(desired-s.yaw));s.yaw+=delta*Math.min(1,dt*11);const nx=clamp(s.x+dx*moveSpeed*dt,-LIMIT,LIMIT),nz=clamp(s.z+dz*moveSpeed*dt,-LIMIT,LIMIT);if(!blockedByBuild(nx,nz)&&!trees.some(t=>t.g.visible&&Math.hypot(nx-t.x,nz-t.z)<t.r+.25)){s.x=nx;s.z=nz}}tick(s,dt,{running,warm:nearFire()||sheltered(),cold:biomeIndex(s.x,s.z)===3});attackCooldown=Math.max(0,attackCooldown-dt);attackTime=Math.max(0,attackTime-dt);wolfTick(dt);refreshResources();if(s.health<=0){death();return}actor.root.position.set(s.x,walkHeight(s.x,s.z)+jumpY,s.z);actor.root.rotation.y=s.yaw;walkPhase+=dt*(moveSpeed>4?12:8);const swing=Math.min(1,moveSpeed/3.6)*.62;actor.legs.forEach((l,i)=>l.rotation.x=Math.sin(walkPhase+i*Math.PI)*swing);actor.arms.forEach((a,i)=>a.rotation.x=-Math.sin(walkPhase+i*Math.PI)*swing*.72);if(jumpY>0){actor.legs.forEach((l,i)=>l.rotation.x=i===0?-.48:.24);actor.arms.forEach(a=>a.rotation.x=-.35)}if(attackTime>0)actor.arms[1].rotation.x=-Math.sin((1-attackTime/.32)*Math.PI)*1.8;actor.body.position.y=Math.abs(Math.sin(walkPhase))*swing*.05;targetHUD();for(const r of resources){if(r.shake>0){r.shake=Math.max(0,r.shake-dt);r.g.rotation.z=Math.sin(r.shake*80)*r.shake*.32}else if(r.g.rotation.z)r.g.rotation.z=0}toastTime-=dt;if(toastTime<=0)$('toast').hidden=true;hudClock+=dt;if(hudClock>.25){hudClock=0;updateHud()}saveClock+=dt;if(saveClock>8){saveClock=0;save()}}
function lighting(t){const hour=s.time/60%24,angle=(hour-6)/24*TAU,daylight=clamp((Math.sin(angle)+.10)*1.3,.08,1),sky=new T.Color(0x18273f).lerp(new T.Color(0xa6bdc1),daylight),gold=Math.max(0,1-Math.abs(Math.sin(angle))*2.3)*daylight;const dir=V(-.75,Math.max(.12,Math.sin(angle)),.36).normalize();worldSky.update(camera.position,daylight,dir,t);meadow.update(s.x,s.z,t);waterMat.bumpMap.offset.set(t*.009,t*.005);scene.background.copy(sky);scene.fog.color.copy(sky);ambient(t,daylight);hemi.intensity=.24+1.28*daylight;sun.intensity=.08+3.45*daylight;sun.color.set(0xffe5bc).lerp(new T.Color(0xffa456),gold*.75);sun.position.set(s.x+dir.x*58,Math.max(13,dir.y*58),s.z+dir.z*58);sun.target.position.set(s.x,height(s.x,s.z),s.z);for(const f of fires){const v=1+.12*Math.sin(t*12+f.x);f.flame.scale.y=.68*v;f.inner.scale.y=.44*v;f.light.intensity=6.5+Math.sin(t*9+f.x)*1.5}ripples.forEach((r,i)=>{r.scale.setScalar(1+i*.65+.3*Math.sin(t*.7+i));r.material.opacity=.055+.025*Math.sin(t+i)})}
function frame(now){const dt=Math.min((now-last)/1000,.045);last=now;if(state==='play')step(dt);const t=now/1000;if(state==='creator'){actor.root.rotation.y=t*.27;const pos=actor.root.position,preview=document.querySelector('.create-preview').getBoundingClientRect();const cx=preview.left+preview.width/2,cy=preview.top+preview.height/2;camera.setViewOffset(innerWidth,innerHeight,innerWidth/2-cx,innerHeight/2-cy,innerWidth,innerHeight);const d=Math.max(3.7,innerHeight/Math.max(160,preview.height)*2.45);camera.position.set(pos.x+.2,pos.y+1.55,pos.z+d);camera.lookAt(pos.x,pos.y+1.18,pos.z)}else{camera.clearViewOffset();const y=walkHeight(s.x,s.z)+1.5+jumpY*.75,dist=sheltered()?Math.min(camDistance,4.5):camDistance;const target=V(s.x-Math.sin(camYaw)*Math.cos(camPitch)*dist,y+Math.sin(camPitch)*dist,s.z-Math.cos(camYaw)*Math.cos(camPitch)*dist);target.y=Math.max(target.y,height(target.x,target.z)+.6);camera.position.lerp(target,Math.min(1,dt*9));camera.lookAt(s.x,y,s.z)}if(building&&state==='play')updateBuild();lighting(t);renderer.render(scene,camera);requestAnimationFrame(frame)}
