window.addEventListener('resize',resize);window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;const k=e.key.length===1?e.key.toLowerCase():e.key;if((state==='play'||state==='bag')&&(['Tab','w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Shift','e','f','i','c',' '].includes(k)||/^[1-9]$/.test(k)))e.preventDefault();if(e.repeat&&!['w','a','s','d','Shift','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k))return;if(k==='Escape'){pause();return}if(k==='b'&&(state==='play'||state==='buildmenu')){e.preventDefault();if(state==='buildmenu')closeBuildMenu();else openBuildMenu();return}if(building&&state==='play'&&(k==='r'||k==='x')){e.preventDefault();if(k==='r'){buildRot=(buildRot+1)%4;updateBuild()}else demolish();return}if(k==='Tab'||k==='i'){state==='bag'?closeBag():openBag('inventory');return}if(/^[1-9]$/.test(k)&&state==='play'){chooseSlot(Number(k)-1);return}if(k==='c'){state==='bag'?closeBag():openBag('craft');return}if(k==='e')interact();else if(k==='f')foodAction();else if(k===' ')jump();else keys.add(k)});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>{keys.clear();if(state==='play'){exitBuild();pause()}});window.addEventListener('pagehide',save);
