const stick=$('stick');let stickId=null;function stickMove(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.max(1,Math.hypot(dx,dy)/32);touchMove={x:dx/d/32,y:dy/d/32};$('knob').style.transform='translate('+dx/d+'px,'+dy/d+'px)'}stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});for(const k of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(k,()=>{stickId=null;touchMove={x:0,y:0};$('knob').style.transform='none'});
